var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IProdutoService, ProdutoService>();
var app = builder.Build();

app.MapGet("/produtos/{id:int}", (int id, IProdutoService svc) =>
    svc.Buscar(id) is { } p ? Results.Ok(p) : Results.NotFound());

app.MapPost("/produtos", (Produto item, IProdutoService svc) =>
{
    var criado = svc.Criar(item);
    return Results.Created($"/produtos/{criado.Id}", criado);
});

app.Run();
